  for(const [,o] of others){ const r=o.p&&o.p.rec; if(!r||typeof r!=='object') continue; const t=num(r.t,-2), at=num(r.at); if(t<-1||t>=MUSIC.length||!(at>0)) continue; if(!best||at>best.at) best={t,at,by:str(o.p.n,12)||'訪客',mine:false}; }
