    let best=null; for(let r=.2;r<2&&!best;r+=.15) for(let a=0;a<6.28;a+=.3){ const xx=back.x+Math.cos(a)*r, zz=back.z+Math.sin(a)*r; if(walkable(xx,zz)){ best={x:xx,z:zz}; break; } }
