    const fx=Array.isArray(p.fx)?p.fx:null; if(o.fxAt===undefined) o.fxAt=fx?fx[1]:null; else if(fx&&fx[1]!==o.fxAt){ o.fxAt=fx[1]; if(typeof fx[0]==='string'&&Date.now()-fx[1]<15000){ showBubble(o,fx[0].slice(0,20)); o.bubT=3.2; } }
