function npcPlace(n,p,yaw){ n.x=p.x; n.z=p.z; if(yaw!=null) n.yaw=yaw; n.path=[]; }
function npcFace(n,p){ n.yaw=Math.atan2(-(p.x-n.x),-(p.z-n.z)); }
// walking: along the house's own route finder; if the way is shut (a closed door) try again, and in the end go round
function npcGo(n,p,then,again){ p=npcSpotFor(n,p); n.goal={x:p.x,z:p.z}; n.then=then||null; n.stuck=0; if(!again) n.unstuck=0; const r=route({x:n.x,z:n.z},p); n.path=(r&&r.length?r.map(q=>({x:q.x,z:q.z})):[{x:p.x,z:p.z}]); n.act='walk'; }
// ---- getting about without sticking or going through things
// the nearest open floor to a point (with a body's width of room when there is any)
function npcNearFree(x,z,R=2){ for(let r=0;r<=R;r+=.15) for(let a=0;a<6.28;a+=r?.35:7){ const xx=x+Math.cos(a)*r, zz=z+Math.sin(a)*r; if(walkable(xx,zz)&&walkable(xx+.18,zz)&&walkable(xx-.18,zz)&&walkable(xx,zz+.18)&&walkable(xx,zz-.18)) return {x:xx,z:zz}; }
  for(let r=0;r<=R;r+=.15) for(let a=0;a<6.28;a+=r?.35:7){ const xx=x+Math.cos(a)*r, zz=z+Math.sin(a)*r; if(walkable(xx,zz)) return {x:xx,z:zz}; } return null; }
// where to stand for a job: a spot inside furniture moves out to the floor beside it, and a spot someone else is already
// standing on moves a step aside, so two people never stand in each other
function npcSpotFor(n,p){ let q=p;
  if(!walkable(q.x,q.z)){ const f=npcNearFree(q.x,q.z,1.1); if(f) q=f; }
  const taken=(x,z)=>{ for(const id in NPC){ const m=NPC[id]; if(m===n||m.g.visible===false) continue; const gx=m.act==='walk'&&m.goal?m.goal.x:m.x, gz=m.act==='walk'&&m.goal?m.goal.z:m.z; if(Math.hypot(gx-x,gz-z)<.35) return true; } return false; };
  if(taken(q.x,q.z)) for(let r=.6;r<=1.5;r+=.3){ let hit=null; for(let a=0;a<6.28&&!hit;a+=.52){ const x=q.x+Math.cos(a)*r, z=q.z+Math.sin(a)*r; if(walkable(x,z)&&!taken(x,z)) hit={x,z}; } if(hit){ q=hit; break; } }
  return q===p?p:{x:q.x,z:q.z}; }
// held up: plan again; then go round by a nearby open spot; at last put them where they were going (out of your sight when
// possible) — never left walking into a wall
function npcUnstick(n,snap){ n.stuck=0; n.unstuck=(n.unstuck||0)+1; const g=n.goal, then=n.then;
  if(n.unstuck>=4&&g&&(Math.hypot(ME.x-n.x,ME.z-n.z)>9||n.unstuck>=6)){ const q=walkable(g.x,g.z)?g:(npcNearFree(g.x,g.z,1)||g); n.x=q.x; n.z=q.z; n.path=[]; n.unstuck=0; npcArrived(n); return; }
  if(snap||!walkable(n.x,n.z)){ const q=npcNearFree(n.x,n.z); if(q){ n.x=q.x; n.z=q.z; } }
  if(n.unstuck>=2&&g){ const q=npcNearFree(n.x+(Math.random()-.5)*2.4,n.z+(Math.random()-.5)*2.4,1.2); if(q){ n.path=(route({x:n.x,z:n.z},q)||[q]).concat(route(q,g)||[{x:g.x,z:g.z}]); n.then=then; n.act='walk'; return; } }
  if(g) npcGo(n,g,then,true); }
// someone else close ahead: a sideways step away from them; of two walking into each other the later one waits
function npcAvoid(n,ux,uz){ let sx=0,sz=0,wait=false; for(const id in NPC){ const m=NPC[id]; if(m===n||m.lie||m.seated||m.g.visible===false) continue;
    const rx=m.x-n.x, rz=m.z-n.z, d=Math.hypot(rx,rz); if(d>.7||d<1e-4) continue; if(rx*ux+rz*uz<=0) continue;
    const left=(rx*-uz+rz*ux)>0; sx+=left?uz:-uz; sz+=left?-ux:ux; if(d<.45&&m.act==='walk'&&id<n.id) wait=true; }
  return (sx||sz||wait)?{x:sx,z:sz,wait}:null; }
function npcArrived(n){ n.path=[];
  // arrived where someone already stands: a half step aside
  for(const id in NPC){ const m=NPC[id]; if(m===n||m.lie||m.seated||m.g.visible===false) continue; if(Math.hypot(m.x-n.x,m.z-n.z)<.33){ for(let a=0;a<6.28;a+=.79){ const x=n.x+Math.cos(a)*.45, z=n.z+Math.sin(a)*.45; if(walkable(x,z)&&Math.hypot(m.x-x,m.z-z)>.4){ n.x=x; n.z=z; break; } } break; } }
  n.act='idle'; const f=n.then; n.then=null; if(f) f(n); }

// ---- subtitles: one speaker at a time, queued
const npcSub=document.createElement('div'); npcSub.id='npcsub';
npcSub.style.cssText='position:fixed;left:50%;bottom:92px;transform:translateX(-50%);max-width:min(640px,86vw);padding:8px 14px;background:#211b16e6;color:#f3ead8;font:16px/1.6 "Noto Serif TC",serif;border-radius:3px;display:none;z-index:30;pointer-events:none;text-align:left';
document.body.append(npcSub);
const subQ=[]; let subUntil=0;
function npcSay(id,text){ if(!text) return; subQ.push({id,text}); if(subQ.length>4) subQ.splice(0,subQ.length-4); }
function tickSub(){ const now=performance.now(); if(now<subUntil) return; if(!subQ.length){ npcSub.style.display='none'; return; }
  const {id,text}=subQ.shift(); npcSub.innerHTML=`<b style="color:#e3c58c;margin-right:.5em">${esc(npcName(id))}</b>${esc(text)}`; npcSub.style.display='block'; subUntil=now+2600+text.length*140;
  const n=NPC[id]; if(n){ n.talk=Math.max(n.talk,performance.now()+3500); n.mouth=performance.now()+1500+text.length*90; } }

// ---- the talk box: choices for the steward and a few questions for the others; keys 1–4 work while looking around
const npcBox=document.createElement('div'); npcBox.id='npcbox';
npcBox.style.cssText='position:fixed;left:50%;bottom:150px;transform:translateX(-50%);display:none;gap:6px;flex-wrap:wrap;justify-content:center;z-index:31';
document.body.append(npcBox);
let boxFor=null;
function npcChoices(id,list){ boxFor=list.length?id:null; npcBox.innerHTML=''; list.forEach(([label,fn],i)=>{ const b=document.createElement('button'); b.type='button'; b.textContent=`${i+1}　${label}`;
    b.style.cssText='font:14px "Noto Serif TC",serif;padding:6px 12px;background:#f3ead8;color:#2a211a;border:1px solid #8a6a48;border-radius:2px;cursor:pointer';
    b.onclick=e=>{ e.stopPropagation(); closeChoices(); fn(); }; npcBox.append(b); }); npcBox.style.display=list.length?'flex':'none'; npcBox._list=list; }
function closeChoices(){ npcBox.style.display='none'; boxFor=null; npcBox._list=null; }
addEventListener('keydown',e=>{ if(!npcBox._list||e.target.tagName==='INPUT') return; const k=Number(e.key); if(k>=1&&k<=npcBox._list.length){ e.preventDefault(); e.stopImmediatePropagation(); const f=npcBox._list[k-1][1]; closeChoices(); f(); } else if(e.key==='Escape') closeChoices(); },true);
function npcBookList(){ closeChoices(); openPanel(NT('ui.book'),'<table style="border-collapse:collapse;line-height:2">'+NPCS.map(d=>`<tr><td style="padding-right:1.2em"><a href="#" data-bio="${d.id}">${esc(npcName(d.id))}</a></td><td style="padding-right:1.2em">${esc(npcFull(d.id))}</td><td style="padding-right:1.2em" class="meta">${esc(NT('bio.'+d.id,0))}</td><td class="meta">${esc(NT('zone.'+({yu:'gate',xu:'porch',chun:'prep',shui:'garden',huo:'kitchen',cai:'well',li:'well',he:'porch',fu:'tearoom',lai:'tearoom'})[d.id]))}</td></tr>`).join('')+'</table>');
  $('#pbody').querySelectorAll('[data-bio]').forEach(a=>a.onclick=e=>{ e.preventDefault(); npcBio(a.dataset.bio); }); }
// one person's profile, from the back office (bio.<id>: a = age and work, b = the profile, one line per paragraph)
function npcBio(id){ openPanel(npcName(id)+'　'+npcFull(id),`<p class="meta">${esc(NT('bio.'+id,0))}</p>`+String(NT('bio.'+id,1)).split(/\n+/).map(t=>`<p style="margin:.5em 0;line-height:1.8">${esc(t)}</p>`).join('')+`<p><a href="#" id="bioBack">← ${esc(NT('ui.book'))}</a></p>`); $('#bioBack').onclick=e=>{ e.preventDefault(); npcBookList(); }; }

// ---- where someone is, for the steward
function whereIs(id){ const n=NPC[id]; const z=npcZone(n); if(!z) return null; return {稱呼:npcName(id),工作區:NT('zone.'+z,0),方向提示:NT('zone.'+z,1)}; }

/* ---- the chains of work ---- */
const CAKE_STEAM=90, CAKE_AGAIN=20*60;   // seconds in the steamer; a new batch twenty minutes after one is served
function cakeSet(st){ NS.cake={st,t:Date.now()}; npcSave(); }
function teaSet(st){ NS.tea.st=st; npcSave(); }
// on loading, make the things in the house agree with the saved progress
function npcRestore(){ const c=NS.cake;
  if(c.st===2&&Date.now()-c.t>CAKE_STEAM*1000) cakeSet(3);
  if(c.st===4) cakeSet(3);                     // she was on her way with it: it is back on the stove ledge
  if(c.st===5&&Date.now()-c.t>CAKE_AGAIN*1000) cakeSet(0);
  if(NS.tea.st==='carrying') teaSet('arrived');
 }
npcRestore();
function propsSync(){ const c=NS.cake.st;
  NPCP.woodAtStove.visible=c>=1&&c<=3;
  NPCP.fire.intensity=c===1||c===2?1.6:c===3?.6:0;
  NPCP.cake.visible=c===3||c===5; if(c===3) NPCP.cake.position.set(NP.stove.x+.55,.88,-3.45); if(c===5) NPCP.cake.position.set(ZP.modern.cx-.85,ZP.modern.h+.01,ZP.modern.cz-.18);
  NPCP.teaGate.visible=NS.tea.st==='arrived'; NPCP.teaStore.visible=NS.tea.st==='stored';
  const bloom=hanxiaoBloom(); for(const f of NPCP.flowers){ f.scale.setScalar(bloom?1:.45); } }
let bloomAt=0, bloomV=false; const hanxiaoBloom=()=>{ if(performance.now()<bloomAt) return bloomV; bloomAt=performance.now()+30000; const h=Number(new Date().toLocaleString('en-US',{timeZone:'Asia/Taipei',hour:'numeric',hour12:false})); return bloomV=h>=7&&h<18; };
const raining=()=>(typeof WX!=='undefined')&&WX.rain>.05;

// what each person does when nothing is asked of them, and the chains
function npcPlan(n){
  if(n.ext&&window.__extPlan&&window.__extPlan(n)) return;
  if(window.__staffPlan&&window.__staffPlan(n)) return;
  if(window.__mealPlan&&window.__mealPlan(n)) return;
  const c=NS.cake.st, now=Date.now();
  if(n.id==='cai'){
    if(NS.tea.st==='arrived') return caiTea(n);
    return caiRound(n); }
  if(n.id==='huo'&&typeof millTime==='function'&&millTime()>=0) return npcGo(n,MILL.at,m=>{ npcFace(m,MILL.c); m.act='mill'; m.busyUntil=Date.now()+15000; });
  if(n.id==='huo'){ if(Math.hypot(n.x-NP.stove.x,n.z-NP.stove.z)>.4){ n.carry=null; return npcGo(n,NP.stove,m=>{ m.yaw=0; m.act='cook'; m.busyUntil=Date.now()+1500; }); } npcPlace(n,NP.stove,0); n.act=c===2?'steam':c===1?'fire':'cook'; n.busyUntil=now+4000; return; }
  if(n.id==='chun'){ if(c===3) return chunFetch(n); n.act=n.writeUntil>now?'write':'prep'; npcGo(n,NP.prep,m=>{ npcFace(m,{x:m.x,z:-4.5}); m.act=m.writeUntil>Date.now()?'write':'prep'; m.busyUntil=Date.now()+8000; }); return; }
  if(n.id==='shui'){ const water=(n.round=(n.round||0)+1)%2===1; npcGo(n,water?NP.garden:NP.gardenB,m=>{ npcFace(m,{x:m.x,z:14.4}); m.act=water?'water':'prune'; m.busyUntil=Date.now()+14000; }); return; }
  if(n.id==='yu'){ const spots=NP.gateSweep; n.si=((n.si||0)+1)%(spots.length+1);
    if(n.si===spots.length) return npcGo(n,{x:NP.stool.x-.1,z:NP.stool.z-.45},m=>{ npcFace(m,{x:47,z:m.z}); m.act='sit'; m.busyUntil=Date.now()+12000; });
    npcGo(n,spots[n.si],m=>{ m.act='sweep'; m.busyUntil=Date.now()+9000; }); return; }
  if(n.id==='xu'){ if(n.lead) return; const si=typeof ZHANG!=='undefined'?ZHANG.si:-1;
    if(si>=0&&n.sSi===si){ n.act=Math.random()<.7?'write':'book'; n.busyUntil=now+20000+Math.random()*20000; return; }
    if(si>=0&&ME.seat!==si&&!occupied(si)){ seatAt(n,si,'dsit',now+30000,m=>{ m.act='write'; if(ZHANG.bellWait){ ZHANG.bellWait=false; npcSay('xu',HF('bell.come')); } }); return; }
    n.pi=((n.pi||0)+1)%2; npcGo(n,NP.porch[n.pi],m=>{ npcFace(m,{x:m.x,z:9.8}); m.act='book'; m.busyUntil=Date.now()+10000; }); return; } }
function caiWood(n){ npcGo(n,NP.woodpile,m=>{ m.act='load'; m.busyUntil=Date.now()+2500; m.next=()=>{ m.carry='wood'; npcGo(m,NP.woodDrop,k=>{ npcFace(k,{x:k.x,z:-4.5});
  if(near(k,9)){ npcSay('cai',npcLine('cai.wood')); npcSay('huo',npcLine('huo.wood')); }
  k.carry=null; cakeSet(1); k.act='unload'; k.busyUntil=Date.now()+2000; NPC.huo.busyUntil=0;
  setTimeout(()=>{ if(NS.cake.st===1){ cakeSet(2); } },8000); }); }; }); }
// 阿財's round: out of the gate to the jetty to draw water from the river, along the road and up the dike to the big banyan,
// buckets down, split wood on the stump under it, then back to the 灶腳 with water at one end of the pole and wood at the
// other. If 火師 is waiting for wood for the 甜粿, this is the load that starts it.
function caiVia(n,pts,then){ if(!pts.length) return then(n); npcGo(n,pts[0],m=>caiVia(m,pts.slice(1),then)); }
function caiRound(n){ const C=CAI;
  npcGo(n,C.dock,m=>{ npcFace(m,{x:m.x+5,z:m.z}); m.act='draw'; m.busyUntil=Date.now()+6000; m.next=()=>{ m.carry='water';
    caiVia(m,[C.road,C.tree],k=>{ k.carry=null; npcFace(k,C.stump); k.act='chop'; k.busyUntil=Date.now()+22000; k.next=()=>{ k.carry='both';
      caiVia(k,[C.road],j=>npcGo(j,NP.woodDrop,i=>{ npcFace(i,{x:i.x,z:-4.5}); i.carry=null; i.act='unload'; i.busyUntil=Date.now()+2500;
        if(NS.cake.st===0){ if(near(i,9)){ npcSay('cai',npcLine('cai.wood')); npcSay('huo',npcLine('huo.wood')); } cakeSet(1); NPC.huo.busyUntil=0; setTimeout(()=>{ if(NS.cake.st===1) cakeSet(2); },8000); }
        else if(near(i,9)) npcSay('cai',npcLine('cai.water')); })); }; }); }; }); }
function caiTea(n){ npcGo(n,{x:NP.stool.x-.3,z:NP.stool.z-.2},m=>{ if(near(m,8)) npcSay('cai',npcLine('cai.tea')); teaSet('carrying'); m.carry='tea'; npcGo(m,NP.store,k=>{ k.carry=null; teaSet('stored'); k.act='unload'; k.busyUntil=Date.now()+2000; }); }); }
function caiWater(n){ npcGo(n,NP.outGate,m=>{ m.g.visible=false; m.act='away'; m.busyUntil=Date.now()+25000; m.next=()=>{ m.g.visible=true; m.carry='water'; npcGo(m,{x:45.6,z:-3.0},k=>{ k.carry=null; k.act='unload'; k.busyUntil=Date.now()+2500; }); }; }); }
function chunFetch(n){ npcGo(n,{x:NP.stove.x+.6,z:-2.6},m=>{ npcFace(m,{x:m.x,z:-4}); if(near(m,9)) npcSay('huo',npcLine('huo.handoff'));
  cakeSet(4); m.carry='cake'; NPC.huo.busyUntil=0;
  npcGo(m,NP.tea,k=>{ npcFace(k,{x:ZP.modern.cx,z:ZP.modern.cz}); k.carry=null; cakeSet(5); if(near(k,7)) npcSay('chun',npcLine('chun.cake')); k.act='prep'; k.busyUntil=Date.now()+6000;
    k.next=()=>{ k.writeUntil=Date.now()+90000; }; }); }); }
const near=(n,r)=>Math.hypot(ME.x-n.x,ME.z-n.z)<r;
// tea comes to the gate some time after one arrives
let teaArriveAt=performance.now()+45000;

/* ---- talking ---- */
function npcTalk(id){ const n=NPC[id]; if(!n||!n.g.visible) return; if(n.lie&&!n.follow){ toast(NT('staff.sleep',Math.random()<.5?0:1),3000); return; } if(n.look||n.pose==='ssit'){ npcSay(id,NT('staff.bath',n.look==='soak'?1:0)); return; }
  n.talk=performance.now()+9000; npcFace(n,ME); if(window.__npcTalk2&&window.__npcTalk2(id)) return; n.talk=performance.now()+9000; npcFace(n,ME); autoMute=performance.now()+20000; closeChoices();
  const c=NS.cake.st, say=k=>npcSay(id,npcLine(k)), VRm=renderer.xr.isPresenting;
  if(id==='yu'){ if(NS.tea.st==='arrived') return say('yu.tea'); if(raining()) return say('yu.rain'); if(n.act==='sweep') return say('yu.sweep'); if(!NS.first){ NS.first=true; npcSave(); return say('yu.first'); } return say('yu.again'); }
  if(id==='xu'){ if(!NS.talked.xu){ NS.talked.xu=true; npcSave(); say('xu.first'); }
    if(n.lead){ return npcChoices(id,[[NT('ui.stop'),()=>leadEnd(true)]]); }
    if(VRm) return leadStart();
    return npcChoices(id,[[NT('ui.lead'),leadStart],[NT('ui.find'),findMenu],[NT('ui.today'),()=>say(c===5?'xu.today':'xu.todayWait')],[NT('ui.self'),()=>{ say('xu.self'); }],[NT('ui.book'),npcBookList]]); }
  if(id==='chun'){ if(n.carry==='cake') return say('chun.tray');
    const opts=[[NT('ui.tea'),()=>say(myMD&&Date.now()-(myMD.at||0)>8000?'chun.served':'chun.ask')],[NT('ui.cake'),()=>say(c===5?'chun.cake':'chun.steaming')]];
    if(n.act==='write') opts.push([NT('ui.write'),()=>say('chun.writing')]);
    say(n.act==='write'||n.act==='prep'?(myMD?'chun.served':'chun.ask'):'chun.ask'); if(!VRm) npcChoices(id,opts); return; }
  if(id==='shui'){ say(n.act==='prune'?'shui.prune':'shui.water');
    if(!VRm) npcChoices(id,[[NT('ui.hanxiao'),()=>say(hanxiaoBloom()?'shui.bloom':'shui.bud')],[NT('ui.prune'),()=>say('shui.prune')]]); return; }
  if(id==='huo'&&mySnack>=0&&SNACKS[mySnack]&&SNACKS[mySnack][2]==='mango'){ setSnack(-1); say('huo.mango'); orderSnack('mangoice','chun'); return; }
  if(id==='huo'){ if(n.act==='mill') return say('huo.mill'); if(c===0) return say('huo.noWood'); if(c===1||c===2) return say('huo.steaming'); if(c===3) return say('huo.handoff'); if(c===4) return say('huo.sent');
    return say(Date.now()-NS.cake.t<8*60000?'huo.sent':'huo.rest'); }
  if(id==='cai'){ if(n.act==='chop') return say('cai.chop'); if(n.carry==='wood'||n.carry==='both') return say('cai.stopped'); if(n.carry==='tea'||NS.tea.st==='arrived') return say('cai.tea'); if(n.carry==='water'||n.act==='draw') return say('cai.water'); return say('cai.stopped'); } }
function findMenu(){ npcChoices('xu',NPCS.filter(d=>d.id!=='xu'&&!d.ext).map(d=>[npcName(d.id),()=>{ const w=whereIs(d.id); npcSay('xu',w?npcLine('xu.find',w):npcLine('xu.findNone')); }])); }
// the steward shows the way to the tea room: he waits at each turn if the guest falls behind, and gives up if they go off
function leadStart(dest,tour){ const n=NPC.xu; dest=dest||{x:NP.teaDoor.x,z:NP.teaDoor.z}; n.lead={t0:performance.now(),lost:0,waitSaid:0,dest,tour:tour||null}; if(!dest.id) npcSay('xu',npcLine('xu.lead'));
  let pts=(route({x:n.x,z:n.z},dest)||[]).slice(); if(!pts.length) pts=[{x:dest.x,z:dest.z}];
  // a guest is shown only to the door of the servants' rooms: stop the walk a step before it goes in
  if(dest.door){ const [x0,x1,z0,z1]=dest.door, inR=(x,z)=>x>x0-.15&&x<x1+.15&&z>z0-.15&&z<z1+.15; let prev={x:n.x,z:n.z}, cut=null;
    for(let i=0;i<pts.length&&!cut;i++){ const q=pts[i], L=Math.hypot(q.x-prev.x,q.z-prev.z); for(let t=0;t<=L;t+=.1){ const x=prev.x+(q.x-prev.x)*t/L, z=prev.z+(q.z-prev.z)*t/L; if(inR(x,z)){ const bk=Math.min(t,1.1); cut={i,p:{x:prev.x+(q.x-prev.x)*(t-bk)/L,z:prev.z+(q.z-prev.z)*(t-bk)/L}}; break; } } prev=q; }
    if(cut) pts=pts.slice(0,cut.i).concat([cut.p]); }
  // keep the corners only, so he walks a little and turns
  const corners=[]; for(let i=0;i<pts.length;i++){ const a=pts[i-1]||{x:n.x,z:n.z}, b=pts[i], c2=pts[i+1]; if(!c2){ corners.push(b); break; } const d1=Math.atan2(b.z-a.z,b.x-a.x), d2=Math.atan2(c2.z-b.z,c2.x-b.x); if(Math.abs(Math.atan2(Math.sin(d1-d2),Math.cos(d1-d2)))>.5||Math.hypot(b.x-a.x,b.z-a.z)>9) corners.push(b); }
  n.lead.corners=corners; n.lead.ci=0; leadNext(n); }
function leadNext(n){ const L=n.lead; if(!L) return; if(L.ci>=L.corners.length){ const D=L.dest;
    if(!D.id){ npcFace(n,{x:-4,z:20}); npcSay('xu',npcLine('xu.arrive')); n.lead=null; setTimeout(()=>{ n.busyUntil=0; n.act='idle'; },6000); n.busyUntil=Date.now()+6000; return; }
    npcFace(n,ME); const fill=Object.assign({地:D.name},typeof titleFill==='function'?titleFill():{}); npcSay('xu',npcLine('h.arrive',fill)); const intro=NT('pl.'+D.id,1); if(intro) npcSay('xu',intro); if(D.door) npcSay('xu',npcLine('h.door',fill));
    if(L.tour){ n.act='tourStop'; L.resume=performance.now()+(intro?16000:9000); return; }
    n.lead=null; n.act='idle'; n.busyUntil=Date.now()+8000; return; }
  const p=L.corners[L.ci++]; npcGo(n,p,m=>{ m.act='waitGuest'; }); }
function leadEnd(said){ const n=NPC.xu; if(!n.lead) return; n.lead=null; if(said) npcSay('xu',npcLine('xu.cancel')); n.path=[]; n.act='idle'; n.busyUntil=0; }
let autoMute=0;

/* ---- each frame ---- */
const npcHint=document.createElement('div'); npcHint.style.cssText='position:fixed;left:50%;bottom:58px;transform:translateX(-50%);padding:3px 10px;background:#29231ee8;color:#f3ead8;font:14px system-ui;border-radius:3px;display:none;z-index:29;pointer-events:none';
document.body.append(npcHint);
let hintFor=null;
addEventListener('keydown',e=>{ if(e.key.toLowerCase()!=='e'||e.repeat||!hintFor||e.target.tagName==='INPUT'||panel.classList.contains('open')) return; e.preventDefault(); e.stopImmediatePropagation(); npcTalk(hintFor); },true);
function npcProximity(n,dist,now){ if(n.lie||n.look||n.pose||n.tl||n.gather||n.lead) return;
  if(n.id==='yu'||n.id==='he'){ const inR=dist<(n.id==='yu'?4.2:2.2); if(inR&&!n.near&&now>(n.lastAuto||0)+30000&&window.__npcNear&&window.__npcNear(n,now)){ n.near=true; n.lastAuto=now; return; } }
  // proximity lines: once on entering range, again only after leaving it and thirty seconds
  const inR=dist<(n.id==='yu'?4.2:2.2); if(!inR){ n.near=false; return; } if(n.near) return; n.near=true;
  if(now<autoMute||now<(n.lastAuto||0)+30000||now<n.talk) return; let k=null;
  if(n.id==='yu'){ if(!NS.first){ NS.first=true; npcSave(); k='yu.first'; } else if(!n.greeted){ k='yu.again'; } else if(raining()&&!n.rainSaid){ n.rainSaid=true; k='yu.rain'; } else if(NS.tea.st==='arrived') k='yu.tea'; else if(n.act==='sweep') k='yu.sweep'; else if(n.wentIn) { k='yu.bye'; n.wentIn=false; } n.greeted=true; }
  if(n.id==='xu'&&!NS.talked.xu){ NS.talked.xu=true; npcSave(); k='xu.first'; }
  if(n.id==='chun'&&n.carry==='cake') k='chun.tray';
  if(n.id==='shui'&&n.act==='water') k='shui.water';
  if(n.id==='huo'&&n.act==='steam') k='huo.steaming'; else if(n.id==='huo'&&n.act==='mill') k='huo.mill';
  if(n.id==='cai'&&(n.carry==='wood'||n.carry==='both')){ k='cai.stopped'; n.wait=Math.max(n.wait,now+1800); } else if(n.id==='cai'&&n.carry==='water') k='cai.water';
  if(k){ n.lastAuto=now; npcSay(n.id,npcLine(k)); } }
function tickNPC(dt){ if(!window.__entered) return; NPC_WALK=true; try{ tickNPC1(dt); } finally{ NPC_WALK=false; } }
function tickNPC1(dt){ const now=performance.now(), nowMs=Date.now();
  tickSub();
  if(NS.cake.st===2&&nowMs-NS.cake.t>CAKE_STEAM*1000) cakeSet(3);
  if(NS.cake.st===5&&nowMs-NS.cake.t>CAKE_AGAIN*1000) cakeSet(0);
  if(NS.tea.st==='none'&&now>teaArriveAt){ teaSet('arrived'); }
  propsSync();
  // steam and the steamer lid
  const steaming=NS.cake.st===2; NPCP.steam.forEach((s,i)=>{ const ph=((now/1000)*.5+i/6)%1; s.position.set(NP.stove.x-.45+Math.sin(i*3+now/900)*.08,1.45+ph*.9,-3.72+Math.cos(i*2)*.06); s.material.opacity=steaming?(1-ph)*.35:0; s.scale.setScalar(.25+ph*.45); });
  NPCP.lid.position.y=1.37+(NPC.huo.act==='lift'?.12:0);
  // the guest has been inside: the gatekeeper will see them off when they come back to the gate
  if(ME.x<44) NPC.yu.wentIn=true;
  let best=null, bestD=1e9; const fx=-Math.sin(ME.yaw), fz=-Math.cos(ME.yaw);
  for(const id in NPC){ const n=NPC[id], P=n.g.userData.parts; const dist=Math.hypot(ME.x-n.x,ME.z-n.z);
    // the steward leading: wait at a corner for the guest, give up if they wander far off
    if(n.lead){ const L=n.lead; if(n.act==='tourStop'){ if(now>L.resume&&dist<8&&window.__butler) window.__butler.tourNext(n); } else if(n.act==='waitGuest'){ if(dist<3.5) leadNext(n); else if(now-L.waitSaid>12000&&dist<18){ L.waitSaid=now; npcSay('xu',npcLine('xu.wait')); } }
      if(dist>25){ L.lost+=dt; if(L.lost>10) leadEnd(false); } else L.lost=0; }
    // talking stops the work; afterwards it carries on
    const talking=now<n.talk;
    if(n.tl&&window.__staffTL) window.__staffTL(n,dt);
    else if(talking&&!n.lie&&!n.pose&&!n.gather){ const want=Math.atan2(-(ME.x-n.x),-(ME.z-n.z)); let dy=want-n.yaw; dy=Math.atan2(Math.sin(dy),Math.cos(dy)); n.yaw+=dy*Math.min(1,dt*4); }
    else if(n.act==='walk'&&n.path.length&&now>n.wait){ const t=n.path[0], dx=t.x-n.x, dz=t.z-n.z, d=Math.hypot(dx,dz);
      // someone in the way, close and ahead: stop and let them by
      const ahead=!n.follow&&dist<.9&&((ME.x-n.x)*dx+(ME.z-n.z)*dz)>0;
      if(ahead&&(n.blockT=(n.blockT||0)+.7)<2.2){ n.wait=now+700; }
      else { if(!ahead) n.blockT=0; const sp=(n.follow||n.errand?1.75:n.speed)*(n.carry?.85:1)*dt; const want=Math.atan2(-dx,-dz); let dy=want-n.yaw; dy=Math.atan2(Math.sin(dy),Math.cos(dy)); n.yaw+=dy*Math.min(1,dt*6);
        if(d<=sp){ n.x=t.x; n.z=t.z; n.path.shift(); if(!n.path.length) npcArrived(n); }
        else { const ux=dx/d, uz=dz/d; let nx=n.x+ux*sp, nz=n.z+uz*sp;
          const av=n.follow?null:npcAvoid(n,ux,uz);
          if(av&&av.wait){ n.wait=now+350; }
          else { if(av){ const L=Math.hypot(av.x,av.z)||1, ax=nx+av.x/L*sp*.7, az=nz+av.z/L*sp*.7; if(walkable(ax,az)){ nx=ax; nz=az; } }
            const here=walkable(n.x,n.z), there=walkable(nx,nz), last=n.path.length===1&&d<.75;   // the last step onto a work spot may be inside a counter's or a bed's margin
            if(there||last||(!here&&(n.offT=(n.offT||0)+sp)<.8)){ n.x=nx; n.z=nz; n.stuck=0; if(there) n.offT=0; }
            else if(!here){ n.offT=0; npcUnstick(n,true); }     // pushed into a wall: out to the nearest floor, never on through it
            else { n.stuck=(n.stuck||0)+dt; if(n.stuck>1.2) npcUnstick(n); } } } } }
    else if(n.act!=='walk'&&!n.lead&&nowMs>(n.busyUntil||0)){ const f=n.next; n.next=null; if(f) f(); else npcPlan(n); }
    // animate: walking legs and arms, work motions, a breath when still
    n.g.position.set(n.x,n.ext?floorY(n.x,n.z):0,n.z); n.g.rotation.y=n.yaw;
    const moving=n.act==='walk'&&!talking&&now>n.wait; n.walkPh+=dt*(moving?7:1.2); const s=Math.sin(n.walkPh);
    P.legs[0].rotation.x=moving?s*.45:0; P.legs[1].rotation.x=moving?-s*.45:0; P.F.position.y=moving?Math.abs(Math.cos(n.walkPh))*.025:Math.sin(n.walkPh)*.004;
    let aL=moving?-s*.3:0, aR=moving?s*.3:0, zL=0, zR=0, headX=0;
    const w=now/1000;
    if(!moving&&!talking){ switch(n.act){
      case 'sweep': aL=.75; aR=.55+Math.sin(w*3)*.25; zR=Math.sin(w*3)*.25; n.toolG&&(n.toolG.rotation.z=Math.sin(w*3)*.4); break;
      case 'book': aL=1.25; aR=.95+Math.sin(w*.7)*.08; headX=.35; break;
      case 'write': aL=.9; aR=.95+Math.sin(w*6)*.05; headX=.5; break;
      case 'prep': aL=.6+Math.sin(w*1.3)*.15; aR=.7; headX=.3; break;
      case 'water': aR=1.0+Math.sin(w*1.4)*.12; aL=.2; headX=.4; break;
      case 'prune': aL=.95; aR=.95+Math.sin(w*5)*.1; headX=.35; break;
      case 'steam': case 'cook': aR=Math.sin(w*.8)>.6?1.6:.6; aL=.5; if(Math.sin(w*.8)>.6) n.act='steam'; headX=.2; break;
      case 'fire': aL=.9; aR=.9; P.F.position.y=-.25; headX=.5; break;
      case 'load': case 'unload': case 'draw': aL=1.1+Math.sin(w*3)*.2; aR=1.1+Math.sin(w*3)*.2; P.F.position.y=-.12; headX=.4; break;
      case 'iron': aR=.85+Math.sin(w*2.2)*.12; zR=-.15; aL=.7; headX=.45; break;
      case 'mend2': aL=.8+Math.sin(w*5)*.05; aR=.85+Math.sin(w*5+1)*.05; headX=.5; break;
      case 'mill': aR=1.05+Math.sin(w*2.2)*.3; zR=-.25+Math.cos(w*2.2)*.2; aL=.75+Math.max(0,Math.sin(w*.7))*.5; headX=.4; break;
      case 'chop': { const k=Math.sin(w*3.2); aL=aR=1.7+k*1.05; P.F.position.y=-.06; headX=.45; break; }
      case 'tie': aL=.9+Math.sin(w*4)*.15; aR=.9-Math.sin(w*4)*.15; P.F.position.y=-.3; headX=.5; break;
      case 'sit': P.F.position.y=-.32; P.legs[0].rotation.x=P.legs[1].rotation.x=1.3; aL=aR=.5; break;
      case 'eat': { const ph=w*1.3+(n.walkPh||0); P.F.position.y=-.33; P.legs[0].rotation.x=P.legs[1].rotation.x=1.35; aL=1.05; aR=Math.sin(ph)>.55?1.5:1.0; headX=Math.sin(ph)>.55?.05:.3; break; }
      case 'wash': aL=.75+Math.sin(w*4)*.12; aR=.75-Math.sin(w*4)*.12; headX=.45; break;
      case 'noodle': aR=1.05+Math.sin(w*5)*.22; aL=.6; headX=.35; break;
      case 'stir': aR=.95+Math.sin(w*6)*.2; aL=.7+Math.sin(w*3)*.1; headX=.3; break; } }
    if(n.id==='huo'){ n.act=n.act==='steam'&&NS.cake.st!==2?'cook':n.act; NPCP.lid.position.y=1.37+(NS.cake.st===2&&aR>1.4?.12:0); }
    // carrying: the tray, the pole with wood, water or tea
    if(n.id==='chun'){ const tray=n.toolG; tray.visible=n.carry==='cake'; if(tray.visible){ aL=aR=1.25; if(!tray.userData.cake){ const c=NPCP.cake.clone(); c.position.set(0,.02,0); c.visible=true; tray.add(c); tray.userData.cake=c; } } }
    { const hid=!!(n.seated||n.look||n.lie||n.pose||n.tl||n.meal);   // tools come out for the work they are for, and stay out between two spots of the same work
      if(n.act==='sweep'||n.act==='water'||n.act==='prune') { n.toolAct=n.act; n.toolT=now; }
      const recent=n.act==='walk'&&n.toolT&&now-n.toolT<25000;
      if(n.toolKind==='broom'&&n.toolG) n.toolG.visible=!hid&&(n.act==='sweep'||(recent&&n.toolAct==='sweep'));
      if(n.toolKind==='can'){ if(n.toolG) n.toolG.visible=!hid&&(n.act==='water'||(recent&&n.toolAct==='water')); if(n.shears) n.shears.visible=!hid&&(n.act==='prune'||(recent&&n.toolAct==='prune')); } }
    if(n.id==='huo'&&n.tray){ n.tray.visible=n.carry==='dish'; if(n.tray.visible){ aL=aR=1.25; } }
    if(n.id==='huo'&&MILL.run){ const on=n.act==='mill'&&!talking&&Math.hypot(n.x-MILL.at.x,n.z-MILL.at.z)<.6; if(on) MILL.run.rotation.y-=dt*2.2; const f=millTime(); MILL.stream.visible=on; MILL.milk.position.y=.02+.22*(f>=0?f:0); MILL.milk.visible=f>=0||on; }
    if(n.id==='cai'&&n.axe){ n.axe.visible=n.act==='chop'&&!talking; CAI.set.visible=n.act==='chop'; }
    if(n.id==='cai'){ const pole=n.toolG, cc=n.carry&&n.carry!=='basin'?n.carry:null; pole.visible=!!cc; if(cc&&pole.userData.what!==cc){ pole.userData.what=cc; npcLoad(pole,cc); } if(cc){ aR=2.6; aL=moving?-s*.3:.2; P.F.position.y-=.02; } }
    P.arms[0].rotation.x+=((aL)-P.arms[0].rotation.x)*Math.min(1,dt*8); P.arms[1].rotation.x+=((aR)-P.arms[1].rotation.x)*Math.min(1,dt*8);
    P.arms[0].rotation.z=zL; P.arms[1].rotation.z=zR; P.head.rotation.x+=(headX*(talking?0:1)-P.head.rotation.x)*Math.min(1,dt*5);
    if(window.__staffPose) window.__staffPose(n,P,dt,w); else n.g.position.y=0;
    // the guest is close and looking at this person: offer to talk
    if(n.g.visible&&dist<2.6&&renderer.xr&&!renderer.xr.isPresenting){ const dot=((n.x-ME.x)*fx+(n.z-ME.z)*fz)/Math.max(.01,dist); if(dot>.8&&dist<bestD){ best=id; bestD=dist; } }
    npcProximity(n,dist,now); }
  hintFor=best; if(best&&!panel.classList.contains('open')){ const t=NT('ui.hint').replace('{稱呼}',npcName(best)); if(npcHint.textContent!==t) npcHint.textContent=t; npcHint.style.display='block'; } else npcHint.style.display='none';
  if(boxFor&&Math.hypot(ME.x-NPC[boxFor].x,ME.z-NPC[boxFor].z)>5) closeChoices(); }
// first plans, and where everyone stands at the start
for(const id in NPC){ const n=NPC[id]; npcFace(n,{x:n.x-1,z:9.8}); n.busyUntil=Date.now()+1500+Math.random()*2000; }
if(NS.cake.st===4||NS.cake.st===5){ npcPlace(NPC.chun,NP.prep); }

